-- AlterTable
ALTER TABLE "events" ADD COLUMN     "city" VARCHAR(100),
ADD COLUMN     "country" VARCHAR(100),
ADD COLUMN     "latitude" DECIMAL(9,6),
ADD COLUMN     "longitude" DECIMAL(9,6);

-- Hand-written CHECK constraint (db/schema.sql is the source of truth) —
-- prevents a half-set coordinate pair (one column populated, the other
-- left null), never generated by Prisma itself. See CLAUDE.md "Critical
-- business rules" for why constraints like this are hand-maintained here.
ALTER TABLE "events" ADD CONSTRAINT "chk_events_lat_lng_paired" CHECK (("latitude" IS NULL) = ("longitude" IS NULL));
